/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PROPOSAL_HEADER
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PROPOSAL   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 3 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PROPOSAL_HK
   hashdiff    : SAT_PROPOSAL_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
*/

with feeders as (
    select
        md5(upper('HUB_PROPOSAL|' || (HUB_PROPOSAL_BK__KGC_PROPOSAL_NUMBER))) as HUB_PROPOSAL_HK
        , BA_LEAD_NO as LEAD_NUMBER
        , cast(null as varchar) as PROPOSAL_FORM_SUBMITTED_INDICATOR
        , cast(null as varchar) as SERVICING_REQUEST_NUMBER
        , 'BJAZ_GP_HOSPITAL_CASH' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_gp_hospital_cash') }}
    where (nullif(trim(KGC_PROPOSAL_NUMBER),'')) is not null
    union all
    select
        md5(upper('HUB_PROPOSAL|' || (HUB_PROPOSAL_BK__SCRUTINY_NO))) as HUB_PROPOSAL_HK
        , cast(null as varchar) as LEAD_NUMBER
        , cast(null as varchar) as PROPOSAL_FORM_SUBMITTED_INDICATOR
        , REQ_NO as SERVICING_REQUEST_NUMBER
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
),

resolved as (
    select
        HUB_PROPOSAL_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LEAD_NUMBER end) as LEAD_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROPOSAL_FORM_SUBMITTED_INDICATOR end) as PROPOSAL_FORM_SUBMITTED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then SERVICING_REQUEST_NUMBER end) as SERVICING_REQUEST_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PROPOSAL_HK
),

hashed as (
    select
        *,
        case when LEAD_NUMBER is not null or PROPOSAL_FORM_SUBMITTED_INDICATOR is not null or SERVICING_REQUEST_NUMBER is not null
                     then md5(upper(coalesce(cast(LEAD_NUMBER as varchar), '') || '|' || coalesce(cast(PROPOSAL_FORM_SUBMITTED_INDICATOR as varchar), '') || '|' || coalesce(cast(SERVICING_REQUEST_NUMBER as varchar), '')))
                end as SAT_PROPOSAL_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PROPOSAL_HK is not null
  and SAT_PROPOSAL_HEADER_HASHDIFF is not null
